"""Outcome graders; code generated by the model executes only in a confined container."""

import json
import re
import subprocess
import tempfile
import uuid
from pathlib import Path, PurePosixPath

NODE_IMAGE = "node:24.11.1-bookworm-slim"


def result(ok, detail):
    return {"status": "pass" if ok else "fail", "detail": detail}


def extract(text):
    text = text.strip()
    match = re.fullmatch(r"```[^\n]*\n(.*?)\n```", text, re.S)
    return match.group(1) if match else text


def safe_path(value):
    if not isinstance(value, str) or not value or "\\" in value:
        return False
    p = PurePosixPath(value)
    return not p.is_absolute() and ".." not in p.parts and value.startswith("src/")


def grade_fsd(case, output):
    edges = output.get("imports")
    if not isinstance(edges, list) or not edges:
        return result(False, "Missing import graph")
    if any(
        not isinstance(e, dict)
        or not safe_path(e.get("from"))
        or not safe_path(e.get("to"))
        for e in edges
    ):
        return result(False, "Import paths must be repository-relative source paths")
    if case["id"] == "checkout-placement":
        form, validation = output.get("form_path"), output.get("validation_path")
        if not safe_path(form) or not safe_path(validation):
            return result(False, "Missing placement paths")
        placement = (
            form.startswith("src/pages/checkout/ui/")
            and validation.startswith("src/pages/checkout/")
            and form != validation
        )
        pairs = {(e["from"], e["to"]) for e in edges}
        required = (form, validation) in pairs and any(
            a == form and b.startswith("src/shared/ui/button") for a, b in pairs
        )
        allowed = all(
            a.startswith("src/pages/checkout/")
            and (
                b.startswith("src/pages/checkout/")
                or b in ("src/shared/ui/button", "src/shared/ui/button/index.ts")
            )
            for a, b in pairs
        )
        return result(
            placement and required and allowed,
            "Checkout-local ownership and permitted dependency graph",
        )
    if case["id"] == "cross-slice":
        expected = {"src/features/checkout", "src/features/cart"}
        targets = {e["to"].removesuffix("/index.ts") for e in edges}
        return result(
            targets == expected
            and all(e["from"] == "src/pages/checkout/ui/page.ts" for e in edges),
            "Page composition of both feature public APIs",
        )
    return result(False, "Unknown FSD case")


def grade_teams(root, case, output):
    original = json.loads((root / "evals" / case["input"]).read_text())
    if case["id"] == "graph":
        attachments = output.get("attachments", [])
        if len(attachments) != 1 or not isinstance(attachments[0].get("content"), str):
            return result(False, "Graph needs one attachment with stringified content")
        attachment = attachments[0]
        if (
            attachment.get("id") != original["attachments"][0]["id"]
            or json.loads(attachment["content"])
            != original["attachments"][0]["content"]
        ):
            return result(False, "Attachment identity or card content changed")
        if "Deployment status" not in output.get("body", {}).get("content", ""):
            return result(False, "Original body text lost")
    else:
        attachments = output.get("attachments", [])
        if len(attachments) != 1 or not isinstance(attachments[0].get("content"), dict):
            return result(False, "Webhook requires one wrapped card")
        card = attachments[0]["content"]
        if card.get("body") != original["body"]:
            return result(False, "Notification content changed")
        actions = card.get("actions", [])
        if (
            len(actions) != 1
            or not isinstance(actions[0], dict)
            or any(
                actions[0].get(k) != v
                for k, v in {
                    "type": "Action.OpenUrl",
                    "title": "View release",
                    "url": "https://example.com/releases/42",
                }.items()
            )
        ):
            return result(False, "Notification action must open the specified release")
    with tempfile.TemporaryDirectory(prefix="skill-card-grade-") as directory:
        path = Path(directory) / "payload.json"
        path.write_text(json.dumps(output))
        checked = subprocess.run(
            [
                "node",
                str(root / "skills/teams-adaptive-cards/scripts/check-teams-card.mjs"),
                "--target",
                case["id"],
                str(path),
            ],
            capture_output=True,
            text=True,
            timeout=10,
        )
        return result(checked.returncode == 0, checked.stdout[-500:])


def grade_javascript(root, case, text):
    image = subprocess.run(
        ["docker", "image", "inspect", NODE_IMAGE], capture_output=True, timeout=10
    )
    if image.returncode:
        return {
            "status": "blocked",
            "detail": f"Pre-pull {NODE_IMAGE} to run isolated JavaScript grading",
        }
    with tempfile.TemporaryDirectory(prefix="skill-js-grade-") as directory:
        folder = Path(directory)
        folder.chmod(0o755)
        (folder / "answer.mjs").write_text(extract(text))
        (folder / "exports.mjs").write_text(
            "import * as answer from './answer.mjs';\nexport const saveAll = answer.saveAll;\nexport const rank = answer.rank;\n"
        )
        sentinel = "verified-" + uuid.uuid4().hex
        checker = (
            (root / "evals/graders/javascript.mjs")
            .read_text()
            .replace("Behavior checks passed", sentinel)
        )
        container = folder.name
        try:
            checked = subprocess.run(
                [
                    "docker",
                    "run",
                    "--name",
                    container,
                    "--rm",
                    "-i",
                    "--pull=never",
                    "--network=none",
                    "--read-only",
                    "--cap-drop=ALL",
                    "--security-opt=no-new-privileges",
                    "--pids-limit=64",
                    "--memory=128m",
                    "--cpus=1",
                    "--user=65534:65534",
                    "--mount",
                    f"type=bind,src={folder},dst=/eval,readonly",
                    "--workdir=/eval",
                    NODE_IMAGE,
                    "node",
                    "--input-type=module",
                    "-",
                    case["id"],
                ],
                input=checker,
                capture_output=True,
                text=True,
                timeout=20,
            )
        except subprocess.TimeoutExpired:
            return result(False, "Generated JavaScript exceeded its execution deadline")
        finally:
            subprocess.run(
                ["docker", "rm", "-f", container], capture_output=True, timeout=10
            )
        if checked.returncode in (125, 126, 127):
            return {
                "status": "blocked",
                "detail": "Container could not start the grader",
            }
        ok = checked.returncode == 0 and sentinel in checked.stdout.splitlines()
        return result(
            ok,
            "Behavior checks passed"
            if ok
            else (checked.stderr[-1000:] or "Grader did not complete its assertions"),
        )


def grade(root, case, text):
    try:
        if case["grader"] == "javascript":
            return grade_javascript(root, case, text)
        output = json.loads(extract(text))
        if not isinstance(output, dict):
            return result(False, "Output must be a JSON object")
        if case["grader"] == "teams":
            return grade_teams(root, case, output)
        if case["grader"] == "fsd":
            return grade_fsd(case, output)
        return result(False, "Unknown grader")
    except (ValueError, TypeError, KeyError, AttributeError):
        return result(False, "Output did not satisfy the required structure")
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return {
            "status": "blocked",
            "detail": "Grader dependency missing or execution timeout",
        }
